describe('Animated transitions between async page loads', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's base URL
    });

    it('should display the loading animation during async page load', () => {
        cy.get('button#loadPage').click(); // Trigger the async page load
        cy.get('.loading-animation').should('be.visible'); // Check if loading animation is visible
        cy.get('.loading-animation').should('not.exist'); // Ensure loading animation disappears after load
        cy.url().should('include', '/new-page'); // Verify the new page URL
    });

    it('should not show loading animation if page is already loaded', () => {
        cy.get('button#loadPage').click(); // Trigger the async page load
        cy.get('.loading-animation').should('be.visible'); // Confirm loading animation is visible
        cy.get('.loading-animation').should('not.exist'); // Ensure loading animation disappears after load

        cy.get('button#loadPage').click(); // Trigger the async page load again
        cy.get('.loading-animation').should('not.exist'); // Check that loading animation does not appear again
        cy.url().should('include', '/new-page'); // Verify the new page URL remains the same
    });
});
